  function getCustomerLedgerEntries(cust) {
    const key = customerKey(cust);
    const entries = [];

    loadInvoices().forEach(inv => {
      if (customerKey(inv.customer) !== key) return;
      entries.push({
        date: inv.date,
        serial: inv.number,
        description: `Invoice ${inv.number}` + (inv.rows && inv.rows.length ? " — " + inv.rows.map(r => r.desc).filter(Boolean).join(", ") : ""),
        debit: inv.grand,
        credit: 0,
      });
      if (inv.paidAmount > 0) {
        entries.push({
          date: inv.date,
          serial: inv.number,
          description: `Payment received against ${inv.number}`,
          debit: 0,
          credit: inv.paidAmount,
        });
      }
    });

    loadVouchers().forEach(v => {
      if (v.customerKey !== key) return;
      entries.push({
        date: v.date,
        serial: v.voucherNo,
        description: v.description || (v.type === "payment" ? "Cash Payment" : "Cash Receipt"),
        debit: v.type === "payment" ? v.amount : 0,
        credit: v.type === "payment" ? 0 : v.amount,
      });
    });

    entries.sort((a, b) => a.date.localeCompare(b.date));
    return entries;
  }

  function balanceLabel(n) {
    return fmt(Math.abs(n)) + (n >= 0 ? " (Dr)" : " (Cr)");
  }

  function generateLedger() {
    const custId = $("ledgerCustomer").value;
    if (!custId) { toast("Select a customer"); return; }
    const cust = loadCustomers().find(c => c.id === custId);
    if (!cust) return;

    const from = $("ledgerFrom").value;
    const to = $("ledgerTo").value;
    const allEntries = getCustomerLedgerEntries(cust);

    const opening = (cust.openingBalance || 0) +
      allEntries.filter(e => from && e.date < from).reduce((s, e) => s + e.debit - e.credit, 0);

    const inRange = allEntries.filter(e => (!from || e.date >= from) && (!to || e.date <= to));

    $("ledgerHead").hidden = false;
    $("ledgerLogoImg").src = settings().logo;
    $("ledgerCompanyName").textContent = settings().companyName;
    $("ledgerFromLabel").textContent = from ? formatDisplayDate(from) : "Beginning";
    $("ledgerToLabel").textContent = to ? formatDisplayDate(to) : "Today";
    $("ledgerPrintDate").textContent = formatDisplayDate(todayISO());
    $("ledgerCustName").textContent = cust.name;
    if (cust.whatsapp) {
      $("ledgerCustPhoneWrap").hidden = false;
      $("ledgerCustPhone").textContent = cust.whatsapp;
    } else {
      $("ledgerCustPhoneWrap").hidden = true;
    }

    const tbody = $("ledgerBody");
    tbody.innerHTML = "";
    const openingRow = document.createElement("tr");
    openingRow.className = "ledger-opening-row";
    openingRow.innerHTML = `<td>${from ? formatDisplayDate(from) : "—"}</td><td>OPB</td><td>Opening Balance</td><td>${opening > 0 ? fmt(opening) : ""}</td><td>${opening < 0 ? fmt(-opening) : ""}</td><td>${balanceLabel(opening)}</td>`;
    tbody.appendChild(openingRow);

    let running = opening;
    let totalDebit = 0, totalCredit = 0;
    inRange.forEach(e => {
      running += e.debit - e.credit;
      totalDebit += e.debit;
      totalCredit += e.credit;
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${formatDisplayDate(e.date)}</td>
        <td class="mono">${escapeHtml(e.serial)}</td>
        <td>${escapeHtml(e.description)}</td>
        <td>${e.debit > 0 ? fmt(e.debit) : ""}</td>
        <td>${e.credit > 0 ? fmt(e.credit) : ""}</td>
        <td>${balanceLabel(running)}</td>
      `;
      tbody.appendChild(tr);
    });

    $("ledgerEmpty").hidden = true;
    $("ledgerTotalsWrap").hidden = false;
    $("ledgerTotalDebit").textContent = fmt(totalDebit);
    $("ledgerTotalCredit").textContent = fmt(totalCredit);
    $("ledgerClosing").textContent = balanceLabel(running);
  }

  /* ================= REPORTS ================= */
  function setReportRange(kind) {
    const now = new Date();
    let from, to;
    if (kind === "today") {
      from = to = todayISO();
    } else if (kind === "week") {
      const day = now.getDay();
      const monday = new Date(now); monday.setDate(now.getDate() - ((day + 6) % 7));
      from = monday.toISOString().slice(0, 10);
      to = todayISO();
    } else if (kind === "month") {
      from = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0, 10);
      to = todayISO();
    }
    reportRange = { from, to };
    $("repFrom").value = from;
    $("repTo").value = to;
    renderReport();
  }

  function renderReport() {
    const from = $("repFrom").value || reportRange.from;
    const to = $("repTo").value || reportRange.to;
    const list = loadInvoices().filter(i => {
      if (from && i.date < from) return false;
      if (to && i.date > to) return false;
      return true;
    }).sort((a, b) => a.date.localeCompare(b.date));

    const count = list.length;
    const grand = list.reduce((s, i) => s + i.grand, 0);
    const paid = list.reduce((s, i) => s + (i.paidAmount || 0), 0);
    const outstanding = list.reduce((s, i) => s + (i.balanceDue || 0), 0);

    $("repCount").textContent = String(count);
    $("repGrand").textContent = fmt(grand);
    $("repPaid").textContent = fmt(paid);
    $("repOutstanding").textContent = fmt(outstanding);

    const tbody = $("reportBody");
    tbody.innerHTML = "";
    $("reportEmpty").hidden = count !== 0;
    list.forEach(inv => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td class="mono">${escapeHtml(inv.number)}</td>
        <td>${formatDisplayDate(inv.date)}</td>
        <td>${escapeHtml(inv.customer.name)}</td>
        <td><span class="status-badge ${inv.paymentStatus || "unpaid"}">${statusLabel(inv.paymentStatus)}</span></td>
        <td class="mono">${fmt(inv.grand)}</td>
        <td class="mono">${fmt(inv.balanceDue || 0)}</td>
      `;
      tbody.appendChild(tr);
    });

    $("repPrintRange").textContent = (from ? formatDisplayDate(from) : "All time") + " – " + (to ? formatDisplayDate(to) : "today");
  }

